ALTER TABLE public.profiles ADD COLUMN auth_user_id uuid UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, profile_id uuid UNIQUE NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('admin','manager','caller')), UNIQUE(user_id));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
COMMENT ON COLUMN public.profiles.role IS 'DEPRECATED: authorization uses protected public.user_roles';
CREATE FUNCTION public.current_org_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT organization_id FROM public.profiles WHERE auth_user_id = auth.uid() $$;
CREATE FUNCTION public.current_profile_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT id FROM public.profiles WHERE auth_user_id = auth.uid() $$;
CREATE FUNCTION public.is_org_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin') $$;
REVOKE ALL ON FUNCTION public.current_org_id(), public.current_profile_id(), public.is_org_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.current_org_id(), public.current_profile_id(), public.is_org_admin() TO authenticated, service_role;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR profile_id IN (SELECT id FROM public.profiles WHERE organization_id = public.current_org_id()));
DO $$ DECLARE p record; BEGIN FOR p IN SELECT tablename, policyname FROM pg_policies WHERE schemaname='public' AND tablename IN ('organizations','profiles','user_scores','incoming_calls') LOOP EXECUTE format('DROP POLICY %I ON public.%I', p.policyname,p.tablename); END LOOP; END $$;
REVOKE ALL ON public.organizations FROM anon, authenticated;
GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.safe_organizations() RETURNS TABLE(id uuid, name text, voipzeker_outbound_number text, has_ghl_key boolean, voipzeker_connected boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT o.id,o.name,o.voipzeker_outbound_number,coalesce(o.ghl_api_key,'') <> '',coalesce(o.voipzeker_login_token,'') <> '' FROM public.organizations o WHERE o.id = public.current_org_id() $$;
REVOKE ALL ON FUNCTION public.safe_organizations() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.safe_organizations() TO authenticated;
REVOKE ALL ON public.profiles, public.user_scores, public.incoming_calls FROM anon, authenticated;
GRANT SELECT ON public.profiles TO authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_scores, public.incoming_calls TO authenticated;
GRANT ALL ON public.profiles, public.user_scores, public.incoming_calls TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_scores ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.incoming_calls ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_org_read ON public.profiles FOR SELECT TO authenticated USING (organization_id = public.current_org_id());
CREATE POLICY scores_org ON public.user_scores FOR ALL TO authenticated USING (organization_id = public.current_org_id()) WITH CHECK (organization_id = public.current_org_id());
CREATE POLICY incoming_org ON public.incoming_calls FOR ALL TO authenticated USING (organization_id = public.current_org_id()) WITH CHECK (organization_id = public.current_org_id());
ALTER TABLE public.user_scores ALTER COLUMN organization_id SET DEFAULT public.current_org_id();
ALTER TABLE public.incoming_calls ALTER COLUMN organization_id SET DEFAULT public.current_org_id();
CREATE FUNCTION public.limit_team_size() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.organization_id IS NULL THEN RAISE EXCEPTION 'Organization is required'; END IF; PERFORM 1 FROM public.organizations WHERE id=NEW.organization_id FOR UPDATE; IF (TG_OP='INSERT' OR NEW.organization_id IS DISTINCT FROM OLD.organization_id) AND (SELECT count(*) FROM public.profiles WHERE organization_id=NEW.organization_id AND id<>NEW.id)>=5 THEN RAISE EXCEPTION 'Maximaal 5 medewerkers per organisatie'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_team_limit BEFORE INSERT OR UPDATE OF organization_id ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.limit_team_size();
CREATE FUNCTION public.link_invited_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE pid uuid; r text; BEGIN SELECT id,role INTO pid,r FROM public.profiles WHERE lower(email)=lower(NEW.email) AND auth_user_id IS NULL FOR UPDATE; IF pid IS NULL THEN RAISE EXCEPTION 'No invited employee profile'; END IF; UPDATE public.profiles SET auth_user_id=NEW.id WHERE id=pid; INSERT INTO public.user_roles(user_id,profile_id,role) VALUES(NEW.id,pid,CASE WHEN r IN ('admin','manager') THEN r ELSE 'caller' END); RETURN NEW; END $$;
CREATE TRIGGER link_employee_on_auth_create AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.link_invited_profile();
REVOKE ALL ON FUNCTION public.limit_team_size(),public.link_invited_profile() FROM PUBLIC, anon, authenticated;
CREATE TABLE public.call_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL DEFAULT public.current_org_id() REFERENCES public.organizations(id),contact_id text NOT NULL,company_id text NOT NULL DEFAULT '',company_name text NOT NULL DEFAULT '',contact_name text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',caller_id uuid,caller_name text NOT NULL DEFAULT '',started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,duration_seconds integer,result text,notes text,voys_call_id text,ghl_synced boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.call_sessions TO authenticated;
GRANT ALL ON public.call_sessions TO service_role;
ALTER TABLE public.call_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY sessions_org ON public.call_sessions FOR ALL TO authenticated USING (organization_id=public.current_org_id()) WITH CHECK (organization_id=public.current_org_id());
CREATE TABLE public.call_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL DEFAULT public.current_org_id() REFERENCES public.organizations(id),contact_id text NOT NULL,company_id text NOT NULL DEFAULT '',result text NOT NULL DEFAULT '',caller_id uuid,attempted_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.call_attempts TO authenticated;
GRANT ALL ON public.call_attempts TO service_role;
ALTER TABLE public.call_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY attempts_org ON public.call_attempts FOR ALL TO authenticated USING (organization_id=public.current_org_id()) WITH CHECK (organization_id=public.current_org_id());
CREATE TABLE public.callbacks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL DEFAULT public.current_org_id() REFERENCES public.organizations(id),contact_id text NOT NULL,contact_name text NOT NULL DEFAULT '',company_name text NOT NULL DEFAULT '',scheduled_date date NOT NULL,scheduled_time text NOT NULL DEFAULT '09:00',note text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','done','dismissed')),created_by uuid,assigned_to uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.callbacks TO authenticated;
GRANT ALL ON public.callbacks TO service_role;
ALTER TABLE public.callbacks ENABLE ROW LEVEL SECURITY;
CREATE POLICY callbacks_org ON public.callbacks FOR ALL TO authenticated USING (organization_id=public.current_org_id()) WITH CHECK (organization_id=public.current_org_id());
CREATE TABLE public.dnc_list (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL DEFAULT public.current_org_id() REFERENCES public.organizations(id),phone text NOT NULL,phone_norm text NOT NULL,reason text NOT NULL DEFAULT '',added_by uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,phone_norm));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.dnc_list TO authenticated;
GRANT ALL ON public.dnc_list TO service_role;
ALTER TABLE public.dnc_list ENABLE ROW LEVEL SECURITY;
CREATE POLICY dnc_org ON public.dnc_list FOR ALL TO authenticated USING (organization_id=public.current_org_id()) WITH CHECK (organization_id=public.current_org_id());
CREATE INDEX ON public.call_sessions(organization_id,contact_id);
CREATE INDEX ON public.call_attempts(organization_id,contact_id);
CREATE INDEX ON public.callbacks(organization_id,scheduled_date);
CREATE INDEX ON public.profiles(organization_id);
CREATE FUNCTION public.touch_callback() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER touch_callback BEFORE UPDATE ON public.callbacks FOR EACH ROW EXECUTE FUNCTION public.touch_callback();